/*
 * File:      host_platform.h
 * Generated: 2026-10-22 14:00:00 -04:00
 * Project:   RTLNet Nexys Video firmware, CLI desktop harness
 * Purpose:   Harness-side controls of the host platform (host_platform.c):
 *            console capture for the --demo checks, the register model's set
 *            of present cores, the classifier register model, the protocol
 *            wrapper's CAPS / CPU_CAPS model, the checksum offload register
 *            model with an event log (CTRL writes, STATUS reads, lwIP flag
 *            changes: the order the firmware performs them in) and the reload
 *            counter. The platform services themselves are declared in
 *            src/rtlnet_platform.h.
 */
#ifndef HOST_PLATFORM_H
#define HOST_PLATFORM_H

#include <stdint.h>   /* uint32_t, uintptr_t */

void        host_capture_clear(void);
const char *host_capture_text(void);
void        host_console_echo(int on);
void        host_model_set_core(uintptr_t base, uint32_t id);
uint32_t    host_model_leds(void);
uint32_t    host_model_cls_peek(uint32_t offset);
void        host_model_cls_poke(uint32_t offset, uint32_t value);
int         host_reload_count(void);

/* Protocol wrapper: CAPS.CPU_PATH_PRESENT and CPU_CAPS (bits 16..18 are the optional blocks). */
void        host_model_set_wrapper(int cpu_path, uint32_t cpu_caps);

/* DDR3 path: the arbiter window present or absent, CLK_STATUS calibration bit, the memory window
 * (sparse, 4 KiB pages, emptied by host_model_ddr_clear). Fault injection for the memory test: an
 * address line stuck low (bit number, 0 = none) and an AND mask on every word read (0xFFFFFFFF = none).
 * The arbiter counters count the model's 32-bit accesses; STATUS.ERR is set by host_model_ddr_error(). */
void        host_model_ddr_set(int arbiter_present, int calibrated);
void        host_model_ddr_alias_bit(unsigned bit);
void        host_model_ddr_data_and(uint32_t mask);
void        host_model_ddr_error(void);
void        host_model_ddr_clear(void);
/* Video cores (Phase 1): the CSI2, S2MM and FBUF windows present or absent (reset state), the frames the model has
 * sent and published (frame k lands in slot (k - 1) % 3; a firmware take writes the bar frame of the present mode into
 * the memory window), and whether the firmware holds a slot. */
void        host_model_video_set(int present);
void        host_model_video_frames(uint32_t frames);
int         host_model_video_fw_holds(void);


/* Checksum offload window: present with this CAPS (0 removes it); STATUS.TX_IDLE after this many STATUS
 * reads (0xFFFFFFFF: never); CTRL bits that do not stick; CTRL and counters as the harness sees them. */
/* H.264 encoder register model (ID, VERSION, CAPS, STATUS and the High profile registers; the engine windows read 0): on = 0/1,
 * seam = CAPS bit 20 (HIGH_PROFILE build). host_model_h264_hp sets the High profile status the model reports: module present (the
 * netlist, not the stub), licensed, hp_caps (bits 0 CABAC, 1 8x8 transform) and the license seconds left (0xFFFF unlimited). */
void        host_model_h264_set(int on, int seam);
void        host_model_h264_hp(uint32_t present, uint32_t licensed, uint32_t caps, uint32_t seconds);
uint32_t    host_model_h264_hp_ctrl(void);
uint32_t    host_model_h264_hp_ctrl_t8(void);
uint32_t    host_model_h264_hp_ctrl_auto(void);
void        host_model_h264_t8_counts(uint32_t n8, uint32_t n4);
void        host_model_txo_set(int present, uint32_t caps);
void        host_model_txo_idle_after(uint32_t reads);
void        host_model_txo_stuck(uint32_t mask);
uint32_t    host_model_txo_ctrl(void);
void        host_model_txo_set_ctrl(uint32_t ctrl);

/* Event log: what the firmware did, in order. */
#define HOST_EV_CTRL_WRITE   1   /* CTRL written (value as written) */
#define HOST_EV_STATUS_READ  2   /* STATUS read (value 1 when it returned TX_IDLE) */
#define HOST_EV_FLAGS        3   /* lwIP checksum flags set (value = flags) */
typedef struct {
    int      kind;
    uint32_t value;
} host_event_t;
void                 host_events_clear(void);
unsigned             host_events_count(void);
const host_event_t  *host_event(unsigned index);
void                 host_event_flags(uint32_t flags);

#endif /* HOST_PLATFORM_H */
